import sys

# Read the input
n = int(input())
mishka_wins = 0
chris_wins = 0

# Iterate over each round
for _ in range(n):
    m_i, c_i = map(int, input().split())  # Get Mishka's and Chris' values for this round
    # Compare Mishka's value with Chris' value
    if m_i > c_i:
        mishka_wins += 1  # Increment Mishka's win count if she wins
    elif c_i > m_i:
        chris_wins += 1  # Increment Chris' win count if he wins

# Check the final result of the game
if mishka_wins == chris_wins:
    print("Friendship is magic!^^")  # Print draw if both players have equal wins
elif mishka_wins > chris_wins:
    print("Mishka")  # Print Mishka if she has more wins
else:
    print("Chris")  # Print Chris if he has more wins

